#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 16          /* maximum number of elements in the heap */

int main(int argc, char **argv)
{
    long heap[CAPACITY];
    int size = 0;           /* current number of elements */

    /* No command line arguments → NOOP */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];

        /* INSERT command: I<number> */
        if (arg[0] == 'I') {
            char *endptr;
            long value = strtol(arg + 1, &endptr, 10);

            /* parsing failed (no digits after the 'I') */
            if (endptr == arg + 1) {
                puts("ERR");
                continue;
            }

            /* heap full */
            if (size >= CAPACITY) {
                puts("FULL");
                continue;
            }

            /* insert at the end and percolate up */
            heap[size] = value;
            ++size;

            int idx = size - 1;
            while (idx > 0) {
                int parent = (idx - 1) / 2;
                if (heap[parent] > heap[idx]) {
                    long tmp = heap[parent];
                    heap[parent] = heap[idx];
                    heap[idx] = tmp;
                    idx = parent;
                } else {
                    break;
                }
            }

            printf("INS %ld\n", value);
            continue;
        }

        /* EXTRACT command: X */
        if (strcmp(arg, "X") == 0) {
            if (size == 0) {
                puts("EMPTY");
                continue;
            }

            long min = heap[0];               /* value to output */

            /* move last element to root and shrink heap */
            heap[0] = heap[size - 1];
            --size;

            /* percolate down */
            int idx = 0;
            while (1) {
                int left  = idx * 2 + 1;
                int right = left + 1;

                if (left >= size)               /* no children */
                    break;

                int smallest = left;
                if (right < size && heap[right] < heap[left])
                    smallest = right;

                if (heap[smallest] < heap[idx]) {
                    long tmp = heap[idx];
                    heap[idx] = heap[smallest];
                    heap[smallest] = tmp;
                    idx = smallest;
                } else {
                    break;
                }
            }

            printf("MIN %ld\n", min);
            continue;
        }

        /* Anything else is an error */
        puts("ERR");
    }

    return 0;
}
